css:
.p28-wrap { display: flex; flex-direction: column; gap: var(--s-5); }
.p28-top { display: grid; gap: var(--s-2); }
.p28-top:empty { display: none; }

.p28-blocks { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--s-5); align-items: start; }
.p28-b { display: grid; gap: var(--s-3); align-content: start; min-width: 0; }
.p28-bh { display: grid; padding-bottom: var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p28-q { font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); }
.p28-part { display: grid; gap: var(--s-2); }
.p28-part > .link-btn { justify-self: start; }
.p28-list { display: grid; gap: var(--s-2); }
.p28-legend { font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); max-width: var(--measure); }
.p28-flag { margin-top: var(--s-1); }
.p28-flag .status { align-items: flex-start; }
.p28-flag .status::before { margin-top: var(--mark-sq-top); }   
.p28-state__row { display: grid; gap: var(--s-1); }
.p28-state__row .pg { margin-top: var(--s-1); }
.p28-state__avg { font-size: var(--fs-body); line-height: var(--lh-body); }
.p28-state__avg b { font-weight: var(--fw-bold); }
.p28-rflag { display: flex; align-items: center; justify-content: flex-end; }
@media (max-width: 30rem) { .rec--bar:has(> .p28-rflag) { grid-template-columns: minmax(0, 1fr); grid-template-areas: "body" "value"; row-gap: var(--s-1); } .p28-rflag { justify-content: flex-start; } }

.rec.p28-one { grid-template-columns: minmax(0, 1fr); grid-template-areas: "body"; }

.p28-ex { display: grid; gap: var(--s-1); justify-items: start; padding: var(--s-2) var(--s-3) 0; }
.p28-ex::before, .p28-ex::after { max-width: var(--frame-arm-max); }
.p28-ex__src { font-size: var(--fs-small); line-height: var(--lh-small); font-weight: var(--fw-semibold); color: var(--muted); }
.p28-ex__t { margin: 0; font-size: var(--fs-body); line-height: var(--lh-body); max-width: var(--measure); overflow-wrap: anywhere; }

.p28-basis { padding-top: var(--s-2); border-top: var(--w1) solid var(--rule); font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); font-variant-numeric: tabular-nums; }

.p28-desc { font-size: var(--fs-small); line-height: var(--lh-small); color: var(--muted); max-width: var(--measure); }

.p28-dec { display: grid; gap: var(--s-2); }
.p28-dec__what { font-size: var(--fs-body); line-height: var(--lh-small); font-weight: var(--fw-medium); overflow-wrap: anywhere; }
.p28-dec__date { color: var(--muted); font-weight: var(--fw-regular); font-variant-numeric: tabular-nums; white-space: nowrap; }
.p28-dec__why { margin-top: var(--s-1); font-size: var(--fs-small); line-height: var(--lh-small); overflow-wrap: anywhere; }

.p28-tfail { display: grid; gap: var(--s-2); justify-items: start; }
.p28-tfail .banner { width: 100%; }
.p28-err { --frame-w: var(--w2); }

.p28-reports { display: grid; gap: var(--s-2); align-content: start; }
.p28-hdr { display: flex; align-items: center; justify-content: space-between; gap: var(--s-2); padding-bottom: var(--s-1); border-bottom: var(--w1) solid var(--rule); }
.p28-btnwrap { position: relative; display: inline-flex; }
.p28-tiprow { display: flex; justify-content: flex-end; }
.p28-replist { display: grid; gap: var(--s-2); align-content: start; }
.rec.p28-rep { width: 100%; border: 0; text-align: start; color: var(--ink); cursor: pointer; font: inherit; min-height: calc(var(--hit) + var(--s-2)); }
.p28-replist .rec { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "body value"; }
.p28-replist .rec__title { font-weight: var(--fw-regular); }

.p28-newmark { display: inline-flex; align-items: center; gap: var(--s-1); margin-inline-start: var(--s-2); font-size: var(--fs-cap); line-height: var(--lh-cap); font-weight: var(--fw-semibold); vertical-align: middle; }
.p28-newmark::before { content: ""; width: 0; height: 0; border: calc(var(--status-dot) / 2) solid var(--ink); border-radius: 50%; }

.p28-replist .rec.p28-fail { min-height: calc(var(--hit) + var(--s-2)); }
.p28-fail .status { align-items: flex-start; }
.p28-fail .status::before { margin-top: var(--mark-sq-top); }
@media (max-width: 30rem) { .p28-replist .rec.p28-fail { grid-template-columns: minmax(0, 1fr); grid-template-areas: "body" "value"; } .p28-fail .rec__value { justify-self: start; } }
.p28-msg { display: grid; gap: var(--s-2); justify-items: start; }
.p28-hint { margin-top: var(--s-1); }
.p28-hint .banner { width: 100%; }

.p28-center { min-height: calc(100cqh - 2 * var(--s-3)); display: grid; align-content: center; justify-items: center; gap: var(--s-3); text-align: center; padding: var(--s-5) var(--s-3); }
.p28-center p { max-width: var(--measure); }
.p28-load { justify-content: center; }
.p28-empty { display: grid; gap: var(--s-3); max-width: var(--measure); padding: var(--s-2) 0; }
.p28-empty p { font-size: var(--fs-body); line-height: var(--lh-body); }
.p28-errbox { display: grid; gap: var(--s-3); justify-items: start; width: min(100%, var(--measure)); }
.p28-errbox .banner { width: 100%; }
.p28-report { max-width: var(--measure); margin-inline: auto; display: grid; gap: var(--s-3); text-align: start; }
.p28-report .prose { display: grid; gap: var(--s-2); font-size: var(--fs-body); line-height: var(--lh-body); }
.p28-report .prose h3 { margin-top: var(--s-2); }
.p28-report__foot { display: flex; justify-content: center; padding-top: var(--s-3); }

.app__content:has(.p28-wrap.at-end) { display: flex; flex-direction: column-reverse; }
.app__content:has(.p28-wrap.at-end) > .content { flex: none; }
.p28-wrap.at-focus .p28-b--goals,
.p28-wrap.at-row2 :is(.p28-b--goals, .p28-b--focus),
.p28-wrap.at-changes :is(.p28-b--goals, .p28-b--focus, .p28-b--declared) { display: none; }
@media (min-width: 48rem) and (min-height: 31.25rem) {
  @container content (min-width: 45rem) {
    .p28-blocks { grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .p28-wrap.at-focus .p28-b--goals, .p28-wrap.at-changes .p28-b--declared { display: grid; }
  }
}

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } .tabwrap > .tab { padding-inline: var(--s-1) 1.75rem; font-size: var(--fs-cap); } }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.dialog__head { align-items: center; }
.field__hint { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
